const P11: LessonDef = {
  id: 'm10d11', title: 'Fronting for Emphasis', week: 41, day: 4, month: 10, level: 'C1', xp: 65, duration: '15 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 Fronting (Moving Elements to the Front)',
      content: 'FRONTING means moving a word or phrase to the START of a sentence for emphasis or to link ideas, WITHOUT necessarily inverting. Objects, complements and adverbials can be fronted: "I can\'t stand rudeness" → "Rudeness, I can\'t stand". "She was truly happy" → "Truly happy she was". Fronting draws attention and creates cohesion.',
      examples: [
        { full: 'That film, I could watch a hundred times.', translation: 'Esse filme, eu podia ver cem vezes.' },
        { full: 'Strange as it may seem, he agreed.', translation: 'Por estranho que pareça, ele concordou.' },
        { full: 'His name I will never forget.', translation: 'O nome dele, nunca esquecerei.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'Fronting an OBJECT usually keeps normal word order after it ("That, I like"). But fronting a NEGATIVE or restrictive adverbial forces INVERSION ("Never will I forget"). Learn to tell the difference: ordinary fronting = no inversion; negative/limiting fronting = inversion.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'Money he had; friends he had none.',
      'Brave she certainly was.',
      'This much I know: nothing lasts forever.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Front the object: 'I love this song.'", options:['This song, I love.','This song loves I.','Love this song I.','I this song love.'], answer:'This song, I love.', explanation:"Fronted object + normal order (no inversion).", xp:10 },
    { id:2, type:'multiple_choice', question:"Does ordinary object-fronting need inversion?", options:['No, normal order follows.','Yes, always invert.','Only with pronouns.','Only in questions.'], answer:'No, normal order follows.', explanation:"Fronting an object keeps subject-verb order.", xp:10 },
    { id:3, type:'fill_blank', question:"'His courage I ___ never doubt.' (will/do)", options:['will','do','did','am'], answer:'will', explanation:"Fronted object 'His courage' + normal order 'I will never doubt'.", xp:10 },
    { id:4, type:'write', question:"Translate: 'Esse erro, nunca o esquecerei.'", options:[], answer:'That mistake, I will never forget.', accept:["that mistake, i'll never forget."], explanation:"Fronted object + normal order.", xp:10 },
    { id:5, type:'write', question:"Front the complement: 'The view was breathtaking.' → 'Breathtaking the view ___.' (verb 'be', past)", options:[], answer:'was', explanation:"'Breathtaking the view was': fronted complement.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which fronting is NEGATIVE and needs inversion?", options:['Never before had I felt so free.','This book, I have read twice.','Coffee, she adores.','Happy they were.'], answer:'Never before had I felt so free.', explanation:"'Never before' is negative → inversion required.", xp:10 },
    { id:7, type:'fill_blank', question:"'Strange ___ it may seem, it worked.' (as/that)", options:['as','that','than','which'], answer:'as', explanation:"'Strange as it may seem': a fixed concessive fronting.", xp:15 },
    { id:8, type:'multiple_choice', question:"Front for contrast: 'He had money but no friends.'", options:['Money he had; friends he had none.','Money had he; friends had he none.','He money had; he friends none.','Had money he; had none friends.'], answer:'Money he had; friends he had none.', explanation:"Fronted objects, normal order, for balanced contrast.", xp:15 },
    { id:9, type:'write', question:"Translate: 'Por muito difícil que fosse, nunca desistiu.'", options:[], answer:'Difficult as it was, she never gave up.', explanation:"'Difficult as it was' = concessive fronting (however difficult).", xp:15 },
    { id:10, type:'write', question:"Front the object: 'She understood the risk.' → 'The risk she ___.' (understood)", options:[], answer:'understood', explanation:"'The risk she understood': fronted object, normal order.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Which sentence fronts a complement correctly?", options:['So generous was she that she gave everything away.','So generous she was that gave everything away.','Generous so was she that everything gave away.','She so generous was that gave everything.'], answer:'So generous was she that she gave everything away.', explanation:"With 'So + adjective' fronted, inversion follows.", xp:15 },
    { id:12, type:'write', question:"'Try ___ he might, he could not open the door.' (as/that)", options:[], answer:'as', explanation:"'Try as he might' = however hard he tried.", xp:15 },
    { id:13, type:'translation', question:"Translate: 'Coragem, tinha-a de sobra; paciência, nem por isso.'", options:['Courage, she had in abundance; patience, not so much.','Courage had she in abundance; patience not so much had.','She courage had abundance; she patience not.','Had courage she abundance; had patience not she.'], answer:'Courage, she had in abundance; patience, not so much.', explanation:"Fronted objects for balanced contrast.", xp:20 },
    { id:14, type:'multiple_choice', question:"Which needs NO inversion?", options:['That decision, we would later regret.','Rarely do we regret kindness.','Never had we regretted it.','Little did we regret it.'], answer:'That decision, we would later regret.', explanation:"Ordinary object-fronting → no inversion.", xp:20 },
    { id:15, type:'write', question:"Complete concessive fronting: 'Rich ___ he was, he lived simply.' (as/though)", options:[], answer:'as', accept:['though'], explanation:"'Rich as he was' / 'Rich though he was' = although he was rich.", xp:15 },
    { id:16, type:'write', question:"Translate: 'Isto eu sei: nada é permanente.'", options:[], answer:'This I know: nothing is permanent.', explanation:"Fronted object 'This' + normal order 'I know'.", xp:20 },
    { id:17, type:'multiple_choice', question:"Choose the correctly fronted adverbial (no inversion):", options:['With great difficulty, she climbed the last few metres.','With great difficulty climbed she the last few metres.','With great difficulty did she climb the last metres.','Climbed she with great difficulty the last metres.'], answer:'With great difficulty, she climbed the last few metres.', explanation:"Fronted non-negative adverbial → normal order.", xp:15 },
    { id:18, type:'fill_blank', question:"'Much ___ I admire her, I cannot agree.' (as/though)", options:['as','though','that','so'], answer:'as', accept:['though'], explanation:"'Much as I admire her' = although I greatly admire her.", xp:20 },
    { id:19, type:'multiple_choice', question:"Which uses fronting for cohesion (linking to the previous idea)?", options:['These problems we can solve; those we cannot.','We can solve these problems; cannot those we.','Solve these problems we can; those cannot.','We these can solve problems; those we cannot.'], answer:'These problems we can solve; those we cannot.', explanation:"Fronting 'these/those' links and contrasts ideas.", xp:15 },
    { id:20, type:'translation', question:"Translate: 'Por mais que tentasse, não conseguia esquecê-la.'", options:['Try as he might, he could not forget her.','As he might try, he could not forget her.','He try as might, could not forget her.','Might he try as, he could not forget her.'], answer:'Try as he might, he could not forget her.', explanation:"'Try as he might' = however much he tried.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the most polished sentence:", options:['Talented though he was, he lacked the discipline to succeed.','Though talented was he, he lacked the discipline to succeed.','Talented was he though, discipline he lacked to succeed.','He talented though was, lacked discipline to succeed.'], answer:'Talented though he was, he lacked the discipline to succeed.', explanation:"'Talented though he was' = although he was talented (concessive fronting).", xp:25 },
    { id:22, type:'write', question:"Front the object for emphasis: 'I will treasure these memories forever.' → 'These memories I ___ forever.'", options:[], answer:'will treasure', explanation:"Fronted object + normal order: 'These memories I will treasure forever'.", xp:25 },
    { id:23, type:'write', question:"Translate: 'Por muito que insistissem, ele recusou-se a comprometer os seus valores.'", options:[], answer:'Much as they insisted, he refused to compromise his values.', explanation:"'Much as they insisted' = however much they insisted.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which sentence WRONGLY adds inversion to ordinary fronting?", options:['This truth understand did she only years later.','This truth she understood only years later.','That promise he kept to the end.','Such moments we must cherish.'], answer:'This truth understand did she only years later.', explanation:"Ordinary object-fronting must NOT invert; 'This truth she understood…' is correct.", xp:25 },
    { id:25, type:'fill_blank', question:"'Hard ___ it is to admit, we were wrong.' (as/that)", options:['as','that','than','so'], answer:'as', explanation:"'Hard as it is to admit' = although it is hard to admit.", xp:25 },
    { id:26, type:'write', question:"Rewrite with concessive fronting: 'Although the task was daunting, they pressed on.' → 'Daunting ___ the task was, they pressed on.'", options:[], answer:'as', accept:['though'], explanation:"'Daunting as/though the task was' = although the task was daunting.", xp:30 },
    { id:27, type:'write', question:"Translate: 'Estes valores defenderei; aqueles preconceitos, combaterei até ao fim.'", options:[], answer:'These values I will defend; those prejudices, I will fight to the end.', accept:["these values i'll defend; those prejudices, i'll fight to the end."], explanation:"Parallel fronted objects, normal order, for rhetorical balance.", xp:30 },
    { id:28, type:'multiple_choice', question:"Identify the sentence that mixes fronting types CORRECTLY:", options:['His talent, no one could deny; yet never did he boast of it.','His talent could no one deny; yet never he did boast of it.','Deny his talent no one could; boast of it never he did.','No one his talent could deny; never boast did he of it.'], answer:'His talent, no one could deny; yet never did he boast of it.', explanation:"Ordinary object-fronting (no inversion) + negative fronting 'never did he boast' (inversion).", xp:25 },
    { id:29, type:'fill_blank', question:"'Little ___ she care for fame; her work spoke for itself.' (did/does)", options:['did','does','was','had'], answer:'did', explanation:"Negative 'Little' fronted → inversion: 'Little did she care'.", xp:25 },
    { id:30, type:'translation', question:"Translate: 'Por mais alto que subisse, humilde permaneceu; e essa humildade, ninguém jamais esqueceria.'", options:['However high he rose, humble he remained; and that humility, no one would ever forget.','However high rose he, remained he humble; and that humility forget no one would ever.','High however he rose, he remained humble; and no one that humility would ever forget.','However high he rose, he humble remained; and that humility no one ever would forget.'], answer:'However high he rose, humble he remained; and that humility, no one would ever forget.', explanation:"Concessive 'However high he rose' + fronted complement 'humble he remained' + fronted object 'that humility'.", xp:35 },
  ],
}

const P12: LessonDef = {
  id: 'm10d12', title: 'Emphatic Do / Does / Did', week: 41, day: 5, month: 10, level: 'C1', xp: 65, duration: '15 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 Emphatic "do / does / did"',
      content: 'To add strong emphasis to a positive statement, put DO/DOES/DID before the base verb, even though the sentence is not a question or a negative. "I like it" → "I DO like it" (contradicting doubt). "She knows" → "She DOES know". "He came" → "He DID come". It insists, contradicts, or reassures.',
      examples: [
        { full: 'I do apologise for the confusion.', translation: 'Peço mesmo desculpa pela confusão.' },
        { full: 'She does care about you, believe me.', translation: 'Ela importa-se mesmo contigo, acredita.' },
        { full: 'He did warn us, but we ignored him.', translation: 'Ele bem que nos avisou, mas ignorámo-lo.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'After emphatic do/does/did, the main verb is in its BASE form: "She does WORK hard" (not "works"), "He did GO" (not "went"). Use it to (1) contradict a doubt, (2) show contrast ("I did try, but…"), or (3) sound polite and sincere ("Do come in", "I do hope so").' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'Do sit down and make yourself at home.',
      'I did tell you, you just weren\'t listening.',
      'It does seem unfair, I agree.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Add emphasis: 'I like coffee.'", options:['I do like coffee.','I do likes coffee.','I did like coffee now.','I am like coffee.'], answer:'I do like coffee.', explanation:"do + base verb 'like'.", xp:10 },
    { id:2, type:'fill_blank', question:"'She ___ know the answer, she\'s just shy.' (do/does)", options:['does','do','did','is'], answer:'does', explanation:"3rd person singular → 'does know'.", xp:10 },
    { id:3, type:'multiple_choice', question:"After emphatic 'did', the verb is:", options:['base form','past form','-ing form','past participle'], answer:'base form', explanation:"'He did GO' (base form).", xp:10 },
    { id:4, type:'write', question:"Translate: 'Eu bem que te avisei!'", options:[], answer:'I did warn you!', explanation:"did + base verb 'warn'.", xp:10 },
    { id:5, type:'write', question:"Add emphasis: 'He came to the party.' → 'He ___ come to the party.'", options:[], answer:'did', explanation:"did + base verb 'come'.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which is CORRECT?", options:['She does work hard.','She does works hard.','She do work hard.','She did works hard.'], answer:'She does work hard.', explanation:"does + base verb 'work'.", xp:10 },
    { id:7, type:'fill_blank', question:"'I ___ hope you can come.' (polite emphasis)", options:['do','does','did','am'], answer:'do', explanation:"'I do hope': sincere emphasis.", xp:15 },
    { id:8, type:'multiple_choice', question:"Correct the error: 'He did went home early.'", options:['He did go home early.','He did gone home early.','He does went home early.','He did going home early.'], answer:'He did go home early.', explanation:"After 'did', use base form 'go'.", xp:15 },
    { id:9, type:'translation', question:"Translate: 'Ela importa-se mesmo contigo.'", options:['She does care about you.','She do cares about you.','She did cares about you.','She is care about you.'], answer:'She does care about you.', explanation:"does + base verb 'care'.", xp:15 },
    { id:10, type:'write', question:"Polite invitation: '___ come in!' (emphatic 'do')", options:[], answer:'Do', explanation:"'Do come in!': warm, emphatic invitation.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Which contradicts a doubt best?", options:['I do understand your concern, but I disagree.','I understand do your concern, but I disagree.','I understanding do your concern, but disagree.','Do I understand your concern, but I disagree.'], answer:'I do understand your concern, but I disagree.', explanation:"Emphatic 'do' insists the understanding is genuine.", xp:15 },
    { id:12, type:'fill_blank', question:"'The plan ___ have some flaws, admittedly.' (does/do)", options:['does','do','did','is'], answer:'does', explanation:"'The plan' (singular) → 'does have'.", xp:15 },
    { id:13, type:'write', question:"Translate: 'Ele tentou mesmo ajudar, mas não conseguiu.'", options:[], answer:'He did try to help, but he couldn\'t.', accept:["he did try to help, but he could not."], explanation:"did + base verb 'try'.", xp:20 },
    { id:14, type:'multiple_choice', question:"Find the ERROR: 'They do enjoyed the concert.'", options:['\"enjoyed\" should be \"enjoy\"','\"do\" should be \"does\"','\"do\" should be \"are\"','No error'], answer:'\"enjoyed\" should be \"enjoy\"', explanation:"After 'do', use the base form: 'They do enjoy'.", xp:20 },
    { id:15, type:'write', question:"Add contrastive emphasis: 'I invited her.' → 'I ___ invite her, she just didn\'t reply.'", options:[], answer:'did', explanation:"did + base verb 'invite'.", xp:15 },
    { id:16, type:'write', question:"Translate: 'Reconheço que a proposta tem mesmo mérito.'", options:[], answer:'I admit the proposal does have merit.', explanation:"does + base verb 'have'.", xp:20 },
    { id:17, type:'multiple_choice', question:"Which sounds most sincere and polite?", options:['I do appreciate everything you\'ve done.','I appreciate do everything you\'ve done.','Do I appreciate everything you\'ve done.','I appreciating do everything you\'ve done.'], answer:'I do appreciate everything you\'ve done.', explanation:"'I do appreciate': heartfelt emphasis.", xp:15 },
    { id:18, type:'fill_blank', question:"'Whatever people say, she ___ deserve the award.' (does/did)", options:['does','did','do','is'], answer:'does', explanation:"Present emphasis, singular subject → 'does deserve'.", xp:20 },
    { id:19, type:'multiple_choice', question:"Correct: 'We did enjoyed ourselves, honestly.'", options:['We did enjoy ourselves, honestly.','We do enjoyed ourselves, honestly.','We did enjoying ourselves, honestly.','We are enjoy ourselves, honestly.'], answer:'We did enjoy ourselves, honestly.', explanation:"did + base form 'enjoy'.", xp:15 },
    { id:20, type:'translation', question:"Translate: 'Custa-me admiti-lo, mas ele tinha mesmo razão.'", options:['It pains me to admit it, but he did have a point.','It pains me to admit it, but he does had a point.','It pains me to admit it, but he did had a point.','It pains me to admit it, but he is have a point.'], answer:'It pains me to admit it, but he did have a point.', explanation:"did + base verb 'have'.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the most natural emphatic concession:", options:['I do concede that mistakes were made, but the intentions were good.','I concede do that mistakes were made, but the intentions good.','Do I concede that mistakes were made, but intentions were good.','I conceding do that mistakes were made, but the intentions good.'], answer:'I do concede that mistakes were made, but the intentions were good.', explanation:"'I do concede' emphasises a genuine admission before a 'but'.", xp:25 },
    { id:22, type:'write', question:"Add emphasis to reassure: 'Things will get better.' → 'Things ___ get better, I promise.'", options:[], answer:'do', explanation:"'Things do get better': reassuring emphasis (base verb 'get').", xp:25 },
    { id:23, type:'translation', question:"Translate: 'Apesar de todas as críticas, a reforma trouxe mesmo melhorias reais.'", options:['Despite all the criticism, the reform did bring real improvements.','Despite all the criticism, the reform does brought real improvements.','Despite all the criticism, the reform did brought real improvements.','Despite all the criticism, the reform is bring real improvements.'], answer:'Despite all the criticism, the reform did bring real improvements.', explanation:"did + base verb 'bring'.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which sentence uses emphatic 'do' to overturn an accusation?", options:['\"You never listen!\" \"I DO listen, I just disagree.\"','\"You never listen!\" \"I listen DO, I just disagree.\"','\"You never listen!\" \"DO I listen, I just disagree.\"','\"You never listen!\" \"I listening DO, I disagree.\"'], answer:'\"You never listen!\" \"I DO listen, I just disagree.\"', explanation:"Emphatic 'do' directly contradicts the accusation.", xp:25 },
    { id:25, type:'fill_blank', question:"'The evidence, limited though it is, ___ point to a clear conclusion.' (does/do)", options:['does','do','did','is'], answer:'does', explanation:"'The evidence' (singular) → 'does point'.", xp:25 },
    { id:26, type:'write', question:"Combine concession + emphasis: 'The film is long, but it is genuinely gripping.' → 'Long the film may be, but it ___ grip you from the first scene.'", options:[], answer:'does', explanation:"'it does grip you': emphatic 'does' + base verb.", xp:30 },
    { id:27, type:'write', question:"Translate: 'Por muito que ele negue, sempre gostou dela.'", options:[], answer:'Much as he denies it, he did always love her.', explanation:"did + base verb 'love' (though 'has always loved' is also natural, the emphatic form uses base 'love').", xp:30 },
    { id:28, type:'multiple_choice', question:"Pick the fully correct sentence:", options:['She did say she would help, and help she did.','She did said she would help, and help she did.','She does say she would help, and help did she.','She did say she would help, and helped she did.'], answer:'She did say she would help, and help she did.', explanation:"'did say' (base 'say') + emphatic tail 'help she did' (fronting + emphatic did).", xp:25 },
    { id:29, type:'fill_blank', question:"'Rules ___ matter, but so does compassion.' (do/does)", options:['do','does','did','is'], answer:'do', explanation:"'Rules' (plural) → 'do matter'.", xp:25 },
    { id:30, type:'translation', question:"Translate: 'Reconheço que cometemos erros; mas aprendemos mesmo com eles, e isso fez toda a diferença.'", options:['I do admit we made mistakes; but we did learn from them, and that made all the difference.','I do admitted we made mistakes; but we did learned from them, and that made all the difference.','I do admit we made mistakes; but we does learn from them, and that made all the difference.','I admit do we made mistakes; but we did learn from them, and all the difference that made.'], answer:'I do admit we made mistakes; but we did learn from them, and that made all the difference.', explanation:"'I do admit' + 'we did learn': both emphatic with base verbs.", xp:35 },
  ],
}

const P13: LessonDef = {
  id: 'm10d13', title: 'Intensifiers & Emphatic Structures', week: 41, day: 6, month: 10, level: 'C1', xp: 65, duration: '15 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 So / Such / What & Strong Intensifiers',
      content: 'Several structures add emphasis to adjectives and nouns. SO + adjective/adverb ("so tired"), SUCH + (a) + noun phrase ("such a mess"), WHAT (a) + noun in exclamations ("What a day!"). With EXTREME (ungradable) adjectives we use absolutely/utterly/completely, not "very": "absolutely exhausted", "utterly ridiculous".',
      examples: [
        { full: 'It was such a beautiful ceremony that everyone cried.', translation: 'Foi uma cerimónia tão bonita que todos choraram.' },
        { full: 'What an incredible performance!', translation: 'Que atuação incrível!' },
        { full: 'I was absolutely exhausted after the trip.', translation: 'Fiquei completamente esgotado depois da viagem.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'Rule of thumb: SO + adjective alone; SUCH + (article) + adjective + noun. "So good" but "such a good film". Use "very" with gradable adjectives (very tired) and "absolutely/utterly" with ungradable/extreme ones (absolutely exhausted, utterly impossible), never "very exhausted" or "absolutely tired".' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'She is so talented that offers keep pouring in.',
      'It was such a long journey.',
      'The idea is utterly absurd.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Complete: 'It was ___ interesting film.'", options:['such an','so an','such','so'], answer:'such an', explanation:"such + a/an + adjective + noun.", xp:10 },
    { id:2, type:'fill_blank', question:"'She is ___ kind.' (so/such)", options:['so','such','such a','very much'], answer:'so', explanation:"so + adjective (no noun).", xp:10 },
    { id:3, type:'multiple_choice', question:"Which pairs with an EXTREME adjective?", options:['absolutely freezing','very freezing','so much freezing','such freezing'], answer:'absolutely freezing', explanation:"'Freezing' is ungradable → 'absolutely freezing'.", xp:10 },
    { id:4, type:'write', question:"Translate: 'Que dia lindo!'", options:[], answer:'What a beautiful day!', explanation:"What + a + adjective + noun (exclamation).", xp:10 },
    { id:5, type:'write', question:"Complete: 'It was ___ a mess!' (so/such)", options:[], answer:'such', explanation:"such + a + noun.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which is CORRECT with 'exhausted'?", options:['absolutely exhausted','very exhausted','so much exhausted','such exhausted'], answer:'absolutely exhausted', explanation:"'Exhausted' is extreme → 'absolutely exhausted'.", xp:10 },
    { id:7, type:'fill_blank', question:"'They were ___ good friends.' (so/such)", options:['such','so','very','so much'], answer:'such', explanation:"such + adjective + plural noun (no article).", xp:15 },
    { id:8, type:'multiple_choice', question:"Correct: 'It was so a good idea.'", options:['It was such a good idea.','It was so good idea.','It was such good a idea.','It was so an good idea.'], answer:'It was such a good idea.', explanation:"such + a + adjective + noun.", xp:15 },
    { id:9, type:'write', question:"Translate: 'A ideia é completamente ridícula.'", options:[], answer:'The idea is utterly ridiculous.', explanation:"'Ridiculous' is extreme → 'utterly ridiculous'.", xp:15 },
    { id:10, type:'write', question:"Complete: '___ a shame you couldn\'t come!' (What/How)", options:[], answer:'What', explanation:"'What a shame!': exclamation with a noun.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Complete: 'It was ___ that we stayed all night.'", options:['so fascinating a lecture','such fascinating a lecture','so a fascinating lecture','such fascinating lecture'], answer:'so fascinating a lecture', explanation:"'so + adj + a + noun' is a formal alternative to 'such a fascinating lecture'.", xp:15 },
    { id:12, type:'write', question:"'The results were ___ impressive.' (so/such)", options:[], answer:'so', explanation:"so + adjective (no noun).", xp:15 },
    { id:13, type:'translation', question:"Translate: 'Foi um sucesso tão grande que abriram uma segunda loja.'", options:['It was such a big success that they opened a second shop.','It was so a big success that they opened a second shop.','It was such big a success that they opened a second shop.','It was so big success that they opened a second shop.'], answer:'It was such a big success that they opened a second shop.', explanation:"such + a + adjective + noun + that.", xp:20 },
    { id:14, type:'multiple_choice', question:"Which intensifier is WRONG?", options:['very perfect','absolutely perfect','simply perfect','quite perfect'], answer:'very perfect', explanation:"'Perfect' is ungradable, not 'very perfect'; use 'absolutely perfect'.", xp:20 },
    { id:15, type:'write', question:"Complete the exclamation: '___ nonsense you talk!' (What/How)", options:[], answer:'What', explanation:"'What nonsense!' (uncountable noun, no article).", xp:15 },
    { id:16, type:'translation', question:"Translate: 'Estava tanto frio que o lago congelou.'", options:['It was so cold that the lake froze.','It was such cold that the lake froze.','It was such a cold that the lake froze.','It was so a cold that the lake froze.'], answer:'It was so cold that the lake froze.', explanation:"so + adjective + that.", xp:20 },
    { id:17, type:'multiple_choice', question:"Choose the correct 'how' exclamation:", options:['How generous of you!','What generous of you!','How a generous of you!','Such generous of you!'], answer:'How generous of you!', explanation:"'How + adjective!' (no noun) vs 'What a + noun!'.", xp:15 },
    { id:18, type:'fill_blank', question:"'I\'m ___ starving, I haven\'t eaten all day.' (absolutely/very)", options:['absolutely','very','so much','such'], answer:'absolutely', explanation:"'Starving' is extreme → 'absolutely starving'.", xp:20 },
    { id:19, type:'multiple_choice', question:"Which is correct?", options:['They had such a wonderful time that they extended their stay.','They had so wonderful time that they extended their stay.','They had such wonderful a time that they extended their stay.','They had so a wonderful time that they extended their stay.'], answer:'They had such a wonderful time that they extended their stay.', explanation:"such + a + adjective + noun + that.", xp:15 },
    { id:20, type:'write', question:"Translate: 'Que confusão terrível!'", options:[], answer:'What a terrible mess!', explanation:"What + a + adjective + noun.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the most polished sentence:", options:['So overwhelming was the support that the campaign doubled its target.','Such overwhelming was the support that the campaign doubled its target.','So overwhelming the support was that the campaign doubled its target.','Such overwhelming the support was that the campaign doubled.'], answer:'So overwhelming was the support that the campaign doubled its target.', explanation:"With inversion: 'So + adjective + was + subject + that'.", xp:25 },
    { id:22, type:'write', question:"Rewrite with 'such': 'The storm was so violent that roofs were torn off.' → 'It was ___ violent storm that roofs were torn off.'", options:[], answer:'such a', explanation:"such + a + adjective + noun.", xp:25 },
    { id:23, type:'write', question:"Translate: 'Foi um discurso tão comovente que nem os mais céticos ficaram indiferentes.'", options:[], answer:'It was such a moving speech that even the most sceptical were not left indifferent.', accept:["it was such a moving speech that even the most sceptical weren't left indifferent."], explanation:"such + a + adjective + noun + that.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which uses an intensifier with an ungradable adjective correctly?", options:['The theory is completely flawless in its logic.','The theory is very flawless in its logic.','The theory is so much flawless in its logic.','The theory is such flawless in its logic.'], answer:'The theory is completely flawless in its logic.', explanation:"'Flawless' is ungradable → 'completely flawless', not 'very'.", xp:25 },
    { id:25, type:'fill_blank', question:"'Never had he made ___ a bold claim in public.' (so/such)", options:['such','so','very','so much'], answer:'such', explanation:"such + a + adjective + noun ('such a bold claim').", xp:25 },
    { id:26, type:'write', question:"Turn into an exclamation: 'The scenery is breathtaking.' → '___ breathtaking scenery!' (What/How)", options:[], answer:'What', explanation:"'What breathtaking scenery!' (uncountable noun 'scenery', no article).", xp:30 },
    { id:27, type:'write', question:"Translate: 'A reação foi de tal ordem que o governo foi obrigado a recuar.'", options:[], answer:'Such was the reaction that the government was forced to back down.', explanation:"'Such was the reaction that…': emphatic inversion with 'such'.", xp:30 },
    { id:28, type:'multiple_choice', question:"Pick the sentence with an intensifier error:", options:['I was very devastated by the news.','I was utterly devastated by the news.','I was absolutely devastated by the news.','I was completely devastated by the news.'], answer:'I was very devastated by the news.', explanation:"'Devastated' is extreme → not 'very'; use utterly/absolutely/completely.", xp:25 },
    { id:29, type:'fill_blank', question:"'It is ___ a rare talent that comes along perhaps once in a generation.' (so/such)", options:['such','so','very','so much'], answer:'such', explanation:"such + a + adjective + noun.", xp:25 },
    { id:30, type:'translation', question:"Translate: 'Que privilégio extraordinário foi assistir a um talento tão puro e a uma humildade tão genuína!'", options:['What an extraordinary privilege it was to witness such pure talent and such genuine humility!','How an extraordinary privilege it was to witness so pure talent and so genuine humility!','What extraordinary a privilege it was to witness such pure talent and genuine such humility!','Such extraordinary privilege it was to witness what pure talent and how genuine humility!'], answer:'What an extraordinary privilege it was to witness such pure talent and such genuine humility!', explanation:"'What a(n) + adj + noun' exclamation + 'such + adj + noun' (no article with uncountables).", xp:35 },
  ],
}

