const P21: LessonDef = {
  id: 'm10d21', title: 'Discourse Markers Review', week: 42, day: 7, month: 10, level: 'C1', xp: 70, duration: '16 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 Week 42 Review, Cohesion Mastery',
      content: 'Consolidate every category of discourse marker: contrast (however, whereas, nonetheless), addition/sequence (moreover, firstly, subsequently), cause/result (therefore, owing to, consequently), clarification/example (namely, such as, in other words), stance (admittedly, arguably, frankly), and spoken links (anyway, mind you, by the way). Choosing the right marker is what makes writing flow logically.',
      examples: [
        { full: 'The evidence is thin; nevertheless, it points, arguably, to one conclusion, namely, negligence.', translation: 'As provas são escassas; ainda assim, apontam, poder-se-á dizer, para uma conclusão, nomeadamente, negligência.' },
        { full: 'Costs rose; consequently, and understandably, morale fell.', translation: 'Os custos subiram; consequentemente, e compreensivelmente, a moral caiu.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'Ask what RELATION you want to signal: contrast? result? example? attitude? Then pick a marker of the right register (formal essay vs casual chat) and punctuate it correctly (usually comma after an opening marker). Precise linking is the difference between a list of sentences and a real argument.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'Firstly the cost, secondly the risk; however, the reward outweighs both.',
      'The trial failed; that is, no effect was observed.',
      'Admittedly it\'s hard. Even so, it\'s worth doing.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Contrast marker:", options:['however','therefore','namely','moreover'], answer:'however', explanation:"'However' = contrast.", xp:10 },
    { id:2, type:'multiple_choice', question:"Result marker:", options:['consequently','whereas','such as','admittedly'], answer:'consequently', explanation:"'Consequently' = result.", xp:10 },
    { id:3, type:'fill_blank', question:"'Two players were injured, ___ the captain and the goalkeeper.' (namely/however)", options:['namely','however','therefore','whereas'], answer:'namely', explanation:"'Namely' names specific items.", xp:10 },
    { id:4, type:'write', question:"Translate: 'Além disso, é mais barato.'", options:[], answer:'Moreover, it is cheaper.', accept:["moreover, it's cheaper."], explanation:"'Moreover' = addition.", xp:10 },
    { id:5, type:'write', question:"Fill the cause marker: '___ to the strike, no trains ran.' (Owing)", options:[], answer:'Owing', explanation:"'Owing to + noun' = because of.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which is a STANCE marker?", options:['admittedly','moreover','such as','therefore'], answer:'admittedly', explanation:"'Admittedly' shows attitude (concession).", xp:10 },
    { id:7, type:'fill_blank', question:"'She is strict; ___, she is fair.' (mind you/namely)", options:['mind you','namely','therefore','such as'], answer:'mind you', explanation:"'Mind you' adds a qualifying point.", xp:15 },
    { id:8, type:'multiple_choice', question:"Which gives an EXAMPLE?", options:['for instance','hence','nonetheless','namely'], answer:'for instance', explanation:"'For instance' = example (namely = specific naming).", xp:15 },
    { id:9, type:'write', question:"Translate: 'Por conseguinte, o preço subiu.'", options:[], answer:'Consequently, the price rose.', explanation:"'Consequently' = result.", xp:15 },
    { id:10, type:'write', question:"Fill the rephrasing marker: 'It\'s illegible; ___ other words, unreadable.' (in)", options:[], answer:'in', explanation:"'in other words' rephrases.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Best fit: 'The data are limited; ___, some patterns are already clear.'", options:['nonetheless','therefore','namely','for instance'], answer:'nonetheless', explanation:"Contrast between limited data and clear patterns.", xp:15 },
    { id:12, type:'fill_blank', question:"'The road flooded; ___, the route was closed.' (accordingly/whereas)", options:['accordingly','whereas','namely','for instance'], answer:'accordingly', explanation:"'Accordingly' = as a result.", xp:15 },
    { id:13, type:'translation', question:"Translate: 'Reconhecidamente difícil, mas, ainda assim, necessário.'", options:['Admittedly difficult, but, nonetheless, necessary.','Namely difficult, but, therefore, necessary.','However difficult, but, such as, necessary.','For instance difficult, but, whereas, necessary.'], answer:'Admittedly difficult, but, nonetheless, necessary.', explanation:"'Admittedly' (stance) + 'nonetheless' (contrast).", xp:20 },
    { id:14, type:'multiple_choice', question:"Which marker is WRONG for the relation?", options:['The bridge is unsafe; for instance, it must be closed.','The bridge is unsafe; therefore, it must be closed.','The bridge is unsafe; consequently, it must be closed.','The bridge is unsafe; as a result, it must be closed.'], answer:'The bridge is unsafe; for instance, it must be closed.', explanation:"Closing follows as a RESULT, not as an example, 'for instance' is wrong.", xp:20 },
    { id:15, type:'write', question:"Fill a sequencer: 'To begin with… ___… lastly.' (second)", options:[], answer:'secondly', explanation:"To begin with / secondly / lastly.", xp:15 },
    { id:16, type:'write', question:"Translate: 'Ou seja, o plano falhou.'", options:[], answer:'In other words, the plan failed.', explanation:"'In other words' rephrases/summarises.", xp:20 },
    { id:17, type:'multiple_choice', question:"Which opens a casual aside?", options:['By the way','Consequently','Furthermore','Hence'], answer:'By the way', explanation:"'By the way' introduces a side topic in speech.", xp:15 },
    { id:18, type:'write', question:"'It rained all week; ___, the festival went ahead.' (even so/namely)", options:[], answer:'even so', explanation:"'Even so' = despite that (contrast).", xp:20 },
    { id:19, type:'multiple_choice', question:"Which correctly frames a debatable claim?", options:['Arguably, this is the finest bridge in the region.','Namely, this is the finest bridge in the region.','Such as, this is the finest bridge in the region.','Therefore, this is the finest bridge in the region.'], answer:'Arguably, this is the finest bridge in the region.', explanation:"'Arguably' presents a defensible but debatable claim.", xp:15 },
    { id:20, type:'translation', question:"Translate: 'Devido à chuva, o evento foi adiado; no entanto, ninguém se importou.'", options:['Owing to the rain, the event was postponed; however, nobody minded.','Owing to the rain, the event was postponed; therefore, nobody minded.','Owing to the rain, the event was postponed; namely, nobody minded.','Owing to the rain, the event was postponed; such as, nobody minded.'], answer:'Owing to the rain, the event was postponed; however, nobody minded.', explanation:"'Owing to' (cause) + 'however' (contrast).", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the correctly linked paragraph opener chain:", options:['Firstly … Moreover … However … Therefore …','Firstly … Namely … Such as … For instance …','However … However … However … However …','Therefore … Therefore … Whereas … Namely …'], answer:'Firstly … Moreover … However … Therefore …', explanation:"A logical build: sequence → addition → contrast → result.", xp:25 },
    { id:22, type:'write', question:"Insert the best marker: 'The samples were contaminated; ___, the entire experiment had to be repeated.' (consequently)", options:[], answer:'consequently', accept:['therefore','thus','as a result'], explanation:"Result relation.", xp:25 },
    { id:23, type:'write', question:"Translate: 'A proposta é ambiciosa; além disso, é viável; contudo, exigirá, nomeadamente, um enorme investimento inicial.'", options:[], answer:'The proposal is ambitious; moreover, it is feasible; however, it will require, namely, a huge initial investment.', accept:["the proposal is ambitious; moreover, it's feasible; however, it will require, namely, a huge initial investment."], explanation:"'moreover' (add) + 'however' (contrast) + 'namely' (specify).", xp:30 },
    { id:24, type:'multiple_choice', question:"Identify the sentence with a REGISTER clash:", options:['To conclude the report, and by the way the coffee\'s gone cold, results were strong.','To conclude, the results were strong and merit further study.','In conclusion, the findings support the hypothesis.','Consequently, the committee recommends approval.'], answer:'To conclude the report, and by the way the coffee\'s gone cold, results were strong.', explanation:"'By the way the coffee\'s gone cold' is casual and out of place in a formal conclusion.", xp:25 },
    { id:25, type:'fill_blank', question:"'The city has invested heavily in transport; ___, congestion has fallen by a third.' (as a result/whereas)", options:['as a result','whereas','namely','for instance'], answer:'as a result', explanation:"Result relation between investment and reduced congestion.", xp:25 },
    { id:26, type:'write', question:"Fill the clarifier: 'We must improve retention, ___, keep customers coming back.' (that is)", options:[], answer:'that is', accept:['in other words'], explanation:"'That is / in other words' defines 'retention'.", xp:30 },
    { id:27, type:'write', question:"Translate: 'Sinceramente, o relatório é fraco; no entanto, e para ser justo, foi escrito à pressa, ou seja, merece uma segunda oportunidade.'", options:[], answer:'Frankly, the report is weak; however, and to be fair, it was written in a hurry, that is, it deserves a second chance.', accept:["frankly, the report is weak; however, and to be fair, it was written in a hurry, that's, it deserves a second chance."], explanation:"'Frankly' (stance) + 'however' (contrast) + 'to be fair' (balancing stance) + 'that is' (clarify).", xp:30 },
    { id:28, type:'multiple_choice', question:"Which paragraph uses markers with flawless logic?", options:['Demand fell. Consequently, output was cut. Nevertheless, prices held firm. Admittedly, few had predicted this.','Demand fell. However, output was cut. Namely, prices held firm. For instance, few predicted this.','Demand fell. Such as output was cut. Therefore, prices held firm. Whereas few predicted this.','Demand fell. Moreover output was cut. Consequently prices held firm namely few predicted.'], answer:'Demand fell. Consequently, output was cut. Nevertheless, prices held firm. Admittedly, few had predicted this.', explanation:"Result → contrast → concession, each marker fits its relation.", xp:25 },
    { id:29, type:'fill_blank', question:"'The negotiations stalled; ___, and rather predictably, both sides blamed each other.' (thereafter/namely)", options:['thereafter','namely','such as','for instance'], answer:'thereafter', explanation:"'Thereafter' = after that (sequence in time).", xp:25 },
    { id:30, type:'translation', question:"Translate: 'Em primeiro lugar, faltam fundos; além disso, o prazo é irrealista; consequentemente, e para ser franco, o projeto está condenado, a menos que, nomeadamente, encontremos um novo investidor.'", options:['Firstly, funds are lacking; moreover, the deadline is unrealistic; consequently, and to be frank, the project is doomed, unless, namely, we find a new investor.','Firstly, funds are lacking; however, the deadline is unrealistic; therefore, to be frank, the project is doomed, unless, for instance, we find an investor.','To begin with, funds are lacking; namely, the deadline is unrealistic; consequently, frankly, the project is doomed, unless such as we find an investor.','Firstly, funds lacking are; moreover, the deadline unrealistic is; consequently and frankly, doomed the project is, unless namely a new investor we find.'], answer:'Firstly, funds are lacking; moreover, the deadline is unrealistic; consequently, and to be frank, the project is doomed, unless, namely, we find a new investor.', explanation:"Sequence + addition + result + stance + specification, all correctly matched.", xp:35 },
  ],
}

