const P22: LessonDef = {
  id: 'm10d22', title: 'Nominalisation', week: 43, day: 1, month: 10, level: 'C1', xp: 65, duration: '15 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 Nominalisation (Turning Verbs into Nouns)',
      content: 'Nominalisation is turning a verb or adjective into a NOUN to create a more formal, abstract, "academic" style. "They decided quickly" → "Their quick decision". "The city grew" → "the growth of the city". Academic and official English is dense with nominalisations because they let you pack ideas and be impersonal.',
      examples: [
        { full: 'The government failed to act. → The government\'s failure to act…', translation: 'O governo não agiu. → A incapacidade do governo de agir…' },
        { full: 'Prices increased sharply. → the sharp increase in prices', translation: 'Os preços subiram bastante. → o forte aumento dos preços' },
        { full: 'They discovered the vaccine. → the discovery of the vaccine', translation: 'Descobriram a vacina. → a descoberta da vacina' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'Common noun endings: -tion (decide→decision, react→reaction), -ment (develop→development), -ance/-ence (perform→performance, differ→difference), -al (arrive→arrival, refuse→refusal), -ure (fail→failure), -th (grow→growth). Nominalisation makes writing formal but can feel heavy, use it for precision, not to hide meaning.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'The refusal to compromise doomed the talks.',
      'A significant reduction in emissions is required.',
      'Her appointment as director was announced yesterday.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Noun of 'decide':", options:['decision','decidement','deciding','decisement'], answer:'decision', explanation:"decide → decision (-sion).", xp:10 },
    { id:2, type:'multiple_choice', question:"Noun of 'develop':", options:['development','developation','developness','developal'], answer:'development', explanation:"develop → development (-ment).", xp:10 },
    { id:3, type:'fill_blank', question:"Nominalise: 'They arrived late.' → 'Their late ___ caused problems.'", options:['arrival','arrivation','arriving','arrivement'], answer:'arrival', explanation:"arrive → arrival (-al).", xp:10 },
    { id:4, type:'translation', question:"Translate (nominalised): 'O aumento dos preços preocupa todos.'", options:['The increase in prices worries everyone.','The increasing prices worry to everyone.','That prices increase worries everyone.','Prices to increase worry everyone.'], answer:'The increase in prices worries everyone.', explanation:"'increase' as a noun.", xp:10 },
    { id:5, type:'write', question:"Noun of 'grow':", options:[], answer:'growth', explanation:"grow → growth (-th).", xp:10 },
    { id:6, type:'multiple_choice', question:"Noun of 'fail':", options:['failure','failment','failness','failation'], answer:'failure', explanation:"fail → failure (-ure).", xp:10 },
    { id:7, type:'fill_blank', question:"Nominalise: 'The team performed well.' → 'The team\'s ___ was praised.'", options:['performance','performation','performing','performment'], answer:'performance', explanation:"perform → performance (-ance).", xp:15 },
    { id:8, type:'multiple_choice', question:"Noun of 'refuse':", options:['refusal','refusion','refusement','refuseness'], answer:'refusal', explanation:"refuse → refusal (-al).", xp:15 },
    { id:9, type:'write', question:"Translate (nominalised): 'A descoberta mudou a medicina.'", options:[], answer:'The discovery changed medicine.', explanation:"'discovery' as a noun.", xp:15 },
    { id:10, type:'write', question:"Noun of 'react':", options:[], answer:'reaction', explanation:"react → reaction (-tion).", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Rewrite formally: 'The company expanded rapidly, which surprised analysts.'", options:['The company\'s rapid expansion surprised analysts.','The company rapid expanded surprised analysts.','That the company expanded rapidly surprise analysts.','The rapidly company expansion analysts surprised.'], answer:'The company\'s rapid expansion surprised analysts.', explanation:"expand → expansion; adverb 'rapidly' → adjective 'rapid'.", xp:15 },
    { id:12, type:'fill_blank', question:"Nominalise: 'They resisted fiercely.' → 'Their fierce ___ delayed the project.'", options:['resistance','resistation','resisting','resistment'], answer:'resistance', explanation:"resist → resistance (-ance).", xp:15 },
    { id:13, type:'translation', question:"Translate (nominalised, formal): 'A recusa do governo em negociar agravou a crise.'", options:['The government\'s refusal to negotiate worsened the crisis.','The government refused to negotiate worsened the crisis.','That the government refused negotiating worsened crisis.','The government to refuse negotiate the crisis worsened.'], answer:'The government\'s refusal to negotiate worsened the crisis.', explanation:"refuse → refusal (nominalised subject).", xp:20 },
    { id:14, type:'multiple_choice', question:"Which is the correctly nominalised version of 'We must reduce costs significantly'?", options:['A significant reduction in costs is required.','A significantly reduce of costs is required.','To significant reduce costs is required.','The costs significant reduction requires.'], answer:'A significant reduction in costs is required.', explanation:"reduce → reduction; 'significantly' → 'significant'.", xp:20 },
    { id:15, type:'write', question:"Noun of 'analyse':", options:[], answer:'analysis', explanation:"analyse → analysis.", xp:15 },
    { id:16, type:'write', question:"Translate (nominalised): 'A implementação do plano exigirá tempo.'", options:[], answer:'The implementation of the plan will require time.', explanation:"implement → implementation.", xp:20 },
    { id:17, type:'multiple_choice', question:"Noun of 'differ':", options:['difference','differment','differation','differness'], answer:'difference', explanation:"differ → difference (-ence).", xp:15 },
    { id:18, type:'fill_blank', question:"Nominalise: 'Emissions must be reduced.' → 'A ___ in emissions is essential.'", options:['reduction','reducement','reducing','reductation'], answer:'reduction', explanation:"reduce → reduction.", xp:20 },
    { id:19, type:'multiple_choice', question:"Which sentence is MOST formal (nominalised)?", options:['The introduction of the tax led to widespread protest.','They introduced the tax and people protested a lot.','When the tax came in, everyone protested.','People protested because the tax was introduced.'], answer:'The introduction of the tax led to widespread protest.', explanation:"Nominalisation ('introduction') creates the most formal, compact version.", xp:15 },
    { id:20, type:'write', question:"Translate (nominalised): 'A nomeação dela como diretora foi bem recebida.'", options:[], answer:'Her appointment as director was well received.', explanation:"appoint → appointment.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Rewrite as a single nominalised sentence: 'The population grew and this put pressure on services.'", options:['Population growth put pressure on services.','The population grew put pressure services.','That population grew pressured services put.','Growing the population services pressured.'], answer:'Population growth put pressure on services.', explanation:"grow → growth; the clause becomes a compact noun phrase subject.", xp:25 },
    { id:22, type:'write', question:"Nominalise 'apply': the noun is ___", options:[], answer:'application', explanation:"apply → application.", xp:25 },
    { id:23, type:'write', question:"Translate (formal, nominalised): 'A falta de investimento levou à deterioração das infraestruturas.'", options:[], answer:'The lack of investment led to the deterioration of the infrastructure.', explanation:"Two nominalisations: 'lack' and 'deterioration'.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which over-nominalised sentence is hard to read (a style warning)?", options:['The implementation of the modification of the specification resulted in the cancellation of the operation.','We changed the specs, so the operation was cancelled.','Changing the specs led to the operation being cancelled.','The spec change caused the operation to be cancelled.'], answer:'The implementation of the modification of the specification resulted in the cancellation of the operation.', explanation:"Stacking too many nominalisations makes prose dense and lifeless, clarity matters more than formality.", xp:25 },
    { id:25, type:'fill_blank', question:"Nominalise: 'The two versions differ in one key way.' → 'There is one key ___ between the two versions.'", options:['difference','differment','differentiation','differing'], answer:'difference', explanation:"differ → difference.", xp:25 },
    { id:26, type:'write', question:"Nominalise 'assess': the noun is ___", options:[], answer:'assessment', explanation:"assess → assessment.", xp:30 },
    { id:27, type:'translation', question:"Translate (nominalised): 'A rápida expansão da rede levou a uma melhoria significativa do acesso à internet.'", options:['The rapid expansion of the network led to a significant improvement in internet access.','The network rapidly expanded improved internet access significant.','To rapidly expand the network improved access significant.','The network expansion rapid a significant internet access improvement led.'], answer:'The rapid expansion of the network led to a significant improvement in internet access.', explanation:"expand → expansion; improve → improvement.", xp:30 },
    { id:28, type:'multiple_choice', question:"Which is the best balance of formality and clarity?", options:['The failure to plan led to delays and cost overruns.','The non-existence of the presence of a plan resulted in the occurrence of delays.','No plan meant stuff was late and over budget, basically.','Planning failed so delays and overruns of cost did happen therefore.'], answer:'The failure to plan led to delays and cost overruns.', explanation:"One clean nominalisation ('failure') is formal yet clear; over-nominalising or over-casual both fail.", xp:25 },
    { id:29, type:'fill_blank', question:"Nominalise: 'The bridge collapsed.' → 'The ___ of the bridge shocked the nation.'", options:['collapse','collapsion','collapsement','collapsal'], answer:'collapse', explanation:"'Collapse' is both verb and noun (zero-derivation).", xp:25 },
    { id:30, type:'translation', question:"Translate (formal, nominalised): 'A recusa em reconhecer o problema, aliada à ausência de qualquer investimento, conduziu ao colapso do sistema.'", options:['The refusal to acknowledge the problem, combined with the absence of any investment, led to the collapse of the system.','That they refused to acknowledge the problem, and no investment, the system collapsed led.','To refuse acknowledging the problem, with absent investment, collapsed the system led.','The refusing to acknowledge, and investment absence, to the system collapse led combined.'], answer:'The refusal to acknowledge the problem, combined with the absence of any investment, led to the collapse of the system.', explanation:"Three nominalisations: 'refusal', 'absence', 'collapse'.", xp:35 },
  ],
}

const P23: LessonDef = {
  id: 'm10d23', title: 'Participle Clauses', week: 43, day: 2, month: 10, level: 'C1', xp: 65, duration: '15 min', topic: 'Grammar',
  sections: [
    { type: 'intro', title: '📖 Participle Clauses',
      content: 'Participle clauses compress two clauses into one, making writing tighter and more elegant. PRESENT participle (-ing) for active/simultaneous actions: "Feeling tired, she left". PAST participle (-ed/3rd form) for passive meaning: "Built in 1900, the house needs repair". PERFECT participle (Having + done) for an earlier action: "Having finished, he relaxed".',
      examples: [
        { full: 'Opening the door, she found a letter.', translation: 'Ao abrir a porta, encontrou uma carta.' },
        { full: 'Exhausted by the journey, they slept for hours.', translation: 'Esgotados pela viagem, dormiram horas.' },
        { full: 'Having lost the map, we asked for directions.', translation: 'Tendo perdido o mapa, pedimos indicações.' },
      ] },
    { type: 'tip', title: '💡 Tip', content: 'The subject of the participle clause must match the subject of the main clause, or you get a "dangling participle": "Walking home, the rain started" is WRONG (the rain wasn\'t walking). "Given (that)…", "Considering…", "Assuming…" are set participle openers. Use participle clauses to sound concise and advanced.' },
    { type: 'examples', title: '🗣️ Real Examples', sentences: [
      'Written in haste, the report contained errors.',
      'Not knowing the answer, he stayed silent.',
      'Given the circumstances, we did our best.',
    ]},
  ],
  stage1: [
    { id:1, type:'multiple_choice', question:"Combine: 'She opened the box. She found a ring.'", options:['Opening the box, she found a ring.','Opened the box, she found a ring.','Having opened by the box, she found a ring.','The box opening, she found a ring.'], answer:'Opening the box, she found a ring.', explanation:"Present participle for the active, near-simultaneous action.", xp:10 },
    { id:2, type:'fill_blank', question:"'___ in 1850, the church is a landmark.' (Built/Building)", options:['Built','Building','Have built','To build'], answer:'Built', explanation:"Past participle (passive): the church WAS built.", xp:10 },
    { id:3, type:'multiple_choice', question:"Which shows an EARLIER action?", options:['Having eaten, we left.','Eating, we left.','Eaten, we left.','To eat, we left.'], answer:'Having eaten, we left.', explanation:"Perfect participle 'Having + done' = completed before.", xp:10 },
    { id:4, type:'write', question:"Translate: 'Sentindo-se cansada, foi para a cama.'", options:[], answer:'Feeling tired, she went to bed.', explanation:"Present participle for a state/reason.", xp:10 },
    { id:5, type:'write', question:"Complete: '___ finished the exam, she left the room.' (Having)", options:[], answer:'Having', explanation:"'Having finished' = after finishing.", xp:10 },
    { id:6, type:'multiple_choice', question:"Which is a DANGLING (wrong) participle?", options:['Driving home, the sky turned red.','Driving home, I watched the sky turn red.','While driving home, I saw the sunset.','As I drove home, the sky turned red.'], answer:'Driving home, the sky turned red.', explanation:"'The sky' wasn't driving, the subject doesn't match.", xp:10 },
    { id:7, type:'fill_blank', question:"'___ by the noise, the baby woke up.' (Disturbed/Disturbing)", options:['Disturbed','Disturbing','Having disturb','To disturb'], answer:'Disturbed', explanation:"Past participle (passive): the baby WAS disturbed.", xp:15 },
    { id:8, type:'multiple_choice', question:"Combine: 'He didn't know the way. He used a map.'", options:['Not knowing the way, he used a map.','Not knew the way, he used a map.','Knowing not the way, he used a map.','Having not know the way, he used a map.'], answer:'Not knowing the way, he used a map.', explanation:"Negative present participle: 'Not knowing…'.", xp:15 },
    { id:9, type:'write', question:"Translate: 'Escrito à pressa, o e-mail tinha erros.'", options:[], answer:'Written in haste, the email had errors.', explanation:"Past participle (passive): the email WAS written.", xp:15 },
    { id:10, type:'write', question:"Complete: '___ the circumstances, we did well.' (Given)", options:[], answer:'Given', explanation:"'Given the circumstances' = considering.", xp:15 },
  ],
  stage2: [
    { id:11, type:'multiple_choice', question:"Combine (earlier cause): 'They had spent all their money. They couldn\'t travel.'", options:['Having spent all their money, they couldn\'t travel.','Spending all their money, they couldn\'t travel.','Spent all their money, they couldn\'t travel.','To spend all their money, they couldn\'t travel.'], answer:'Having spent all their money, they couldn\'t travel.', explanation:"Perfect participle for the completed earlier action.", xp:15 },
    { id:12, type:'write', question:"'___ that he was new, they helped him settle in.' (Realising/Realised)", options:[], answer:'Realising', explanation:"Present participle (active) for the reason.", xp:15 },
    { id:13, type:'write', question:"Translate: 'Tendo terminado o trabalho, saímos mais cedo.'", options:[], answer:'Having finished the work, we left early.', explanation:"Perfect participle 'Having finished'.", xp:20 },
    { id:14, type:'multiple_choice', question:"Fix the dangling participle: 'Looking out of the window, the mountains were beautiful.'", options:['Looking out of the window, I saw that the mountains were beautiful.','Looking out of the window, beautiful were the mountains.','The mountains looking out of the window were beautiful.','Looking out of the window the mountains beautiful were.'], answer:'Looking out of the window, I saw that the mountains were beautiful.', explanation:"The subject 'I' must be the one looking.", xp:20 },
    { id:15, type:'write', question:"Complete (passive participle): '___ properly, the machine is very safe.' (Used)", options:[], answer:'Used', explanation:"'Used properly' = when it is used properly (passive).", xp:15 },
    { id:16, type:'translation', question:"Translate: 'Não tendo recebido resposta, voltámos a escrever.'", options:['Having received no reply, we wrote again.','Not receiving reply, we wrote again after.','Received no reply, we wrote again.','To receive no reply, we wrote again.'], answer:'Having received no reply, we wrote again.', explanation:"Negative perfect participle: 'Having received no reply'.", xp:20 },
    { id:17, type:'multiple_choice', question:"Which uses a participle clause for two SIMULTANEOUS actions?", options:['She sat by the fire, reading a book.','She sat by the fire, having read a book elsewhere.','She sat by the fire, read a book.','She sat by the fire, to read a book.'], answer:'She sat by the fire, reading a book.', explanation:"'-ing' participle for the simultaneous action.", xp:15 },
    { id:18, type:'fill_blank', question:"'___ all the evidence, the jury reached a verdict.' (Having considered/Considering)", options:['Having considered','Considering','Considered','To consider'], answer:'Having considered', explanation:"Perfect participle: the considering happened before the verdict.", xp:20 },
    { id:19, type:'multiple_choice', question:"Which is a correct set-phrase participle opener?", options:['Assuming the data is correct, the model holds.','Assumed the data is correct, the model holds.','To assume the data correct, the model holds.','Assumption the data correct, the model holds.'], answer:'Assuming the data is correct, the model holds.', explanation:"'Assuming (that)…' is a fixed participle opener.", xp:15 },
    { id:20, type:'translation', question:"Translate: 'Construída sobre uma colina, a fortaleza dominava a cidade.'", options:['Built on a hill, the fortress dominated the city.','Building on a hill, the fortress dominated the city.','Having built on a hill, the fortress dominated the city.','To build on a hill, the fortress dominated the city.'], answer:'Built on a hill, the fortress dominated the city.', explanation:"Past participle (passive): the fortress WAS built.", xp:20 },
  ],
  stage3: [
    { id:21, type:'multiple_choice', question:"Choose the most elegant combination: 'The report was written by a committee. It reflected many views. It pleased no one.'", options:['Written by a committee and reflecting many views, the report pleased no one.','Writing by a committee, reflected many views, the report pleased no one.','Having written by a committee reflecting views, no one the report pleased.','The report written a committee, reflecting views, pleased no one it.'], answer:'Written by a committee and reflecting many views, the report pleased no one.', explanation:"Past participle (passive) + present participle (active) combined before the main clause.", xp:25 },
    { id:22, type:'write', question:"Combine with a perfect participle: 'She had studied medicine. She understood the risks.' → '___ medicine, she understood the risks.'", options:[], answer:'Having studied', explanation:"'Having studied medicine' = after studying it.", xp:25 },
    { id:23, type:'write', question:"Translate: 'Tendo sido avisados do perigo, os habitantes foram evacuados a tempo.'", options:[], answer:'Having been warned of the danger, the inhabitants were evacuated in time.', explanation:"Perfect passive participle: 'Having been warned'.", xp:30 },
    { id:24, type:'multiple_choice', question:"Which sentence contains a DANGLING participle error?", options:['After reviewing the file, the decision surprised everyone.','After reviewing the file, the manager made a decision.','Having reviewed the file, she decided quickly.','Reviewing the file, I noticed an error.'], answer:'After reviewing the file, the decision surprised everyone.', explanation:"'The decision' didn't review the file, the subject doesn't match the participle.", xp:25 },
    { id:25, type:'fill_blank', question:"'___ properly funded, the programme could transform the region.' (If/Given)", options:['Given','If','Having','Being'], answer:'Given', accept:['If'], explanation:"'Given (that) it were properly funded': 'Given' introduces a condition/premise.", xp:25 },
    { id:26, type:'write', question:"Rewrite concisely: 'Because it was made of glass, the sculpture was fragile.' → '___ of glass, the sculpture was fragile.'", options:[], answer:'Made', explanation:"Past participle (passive) 'Made of glass' = because it was made of glass.", xp:30 },
    { id:27, type:'translation', question:"Translate: 'Considerando todos os fatores, e não tendo encontrado alternativa viável, a comissão recomendou o encerramento.'", options:['Considering all the factors, and having found no viable alternative, the committee recommended closure.','Considered all factors, and finding no viable alternative, the committee recommended closure.','To consider all factors, and not finding alternative, closure the committee recommended.','Considering all factors, and had found no alternative, the committee closure recommended.'], answer:'Considering all the factors, and having found no viable alternative, the committee recommended closure.', explanation:"'Considering…' (present participle) + 'having found no…' (perfect participle).", xp:30 },
    { id:28, type:'multiple_choice', question:"Pick the version that correctly chains participle clauses:", options:['Encouraged by early results and knowing time was short, the team accelerated the trials.','Encouraging by early results and known time was short, the team accelerated.','Having encouraged by results, knowing time short, the team the trials accelerated.','Encouraged by early results, knew time was short, accelerated the team trials.'], answer:'Encouraged by early results and knowing time was short, the team accelerated the trials.', explanation:"Past participle (passive) 'Encouraged' + present participle (active) 'knowing', both with subject 'the team'.", xp:25 },
    { id:29, type:'fill_blank', question:"'___ no further questions, the chair closed the meeting.' (There being/Being there)", options:['There being','Being there','Having there','There having'], answer:'There being', explanation:"'There being no further questions': a formal absolute participle construction.", xp:25 },
    { id:30, type:'write', question:"Translate: 'Erguida no século XVII e restaurada recentemente, a igreja, tendo resistido a guerras e terramotos, permanece o coração da cidade velha.'", options:[], answer:'Built in the 17th century and recently restored, the church, having survived wars and earthquakes, remains the heart of the old town.', explanation:"Past participles ('Built', 'restored') + perfect participle ('having survived') around one subject.", xp:35 },
  ],
}

